package com.xiahu.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import org.json.*;
public final class ReaderSystemUiTest extends Instrumentation{
 static void check(boolean v,String n){if(!v)throw new AssertionError(n);}static Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();Activity a=null;boolean ok=false;try{a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();MainActivity host=(MainActivity)a;FrameLayout root=(FrameLayout)field(host,"root");ReaderSystemUi ui=(ReaderSystemUi)field(host,"readerSystemUi");Thread.sleep(500);int before=root.getPaddingTop();runOnMainSync(()->ui.configure(true,true,"paper"));Thread.sleep(900);waitForIdleSync();runOnMainSync(()->{if(Build.VERSION.SDK_INT>=30){check(!root.getRootWindowInsets().isVisible(WindowInsets.Type.statusBars()),"System status icons hidden");check(root.getRootWindowInsets().isVisible(WindowInsets.Type.navigationBars()),"Navigation remains available");}check(root.getPaddingTop()==before&&before>0,"Original status strip space preserved");LinearLayout strip=(LinearLayout)root.getChildAt(1);check(strip.getVisibility()==View.VISIBLE&&strip.getTop()==0&&strip.getHeight()==before,"Custom strip remains at original status position");check(((TextView)strip.getChildAt(0)).getText().toString().contains(":"),"Clock displayed");check(((TextView)strip.getChildAt(1)).getText().toString().contains("%"),"Battery displayed");});runOnMainSync(()->ui.configure(false,true,"paper"));Thread.sleep(700);runOnMainSync(()->{if(Build.VERSION.SDK_INT>=30)check(root.getRootWindowInsets().isVisible(WindowInsets.Type.statusBars()),"Status restored leaving reader");check(root.getChildAt(1).getVisibility()==View.GONE,"Custom strip removed leaving reader");});out.putString("report",new JSONObject().put("passed",true).put("statusIconsHiddenOnlyDuringReading",true).put("clockAndBatteryAtOriginalStrip",true).put("safeContentHeightUnchanged",true).put("navigationStillVisible",true).put("exitRestoresSystemStatus",true).toString());ok=true;}catch(Throwable e){out.putString("failure",e.toString());}finally{if(a!=null){Activity done=a;runOnMainSync(done::finish);}}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
